// SQLite per-tenant DBs - shard routing demo
function hash(s) { var h = 0; for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h; }
var SHARDS = 4;
var keys = ["user:1", "user:2", "order:9", "order:10", "session:abc"];
console.log("System: SQLite | Shards by: tenant -> file");
keys.forEach(function(k) { console.log("  " + k + " -> shard " + (hash(k) % SHARDS)); });
console.log("Routing: tenant map | Rebalance: move files -> PASS");

